import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.Cxtv3Pj-.js";const u=JSON.parse('{"title":"Building Your Project","description":"","frontmatter":{},"headers":[],"relativePath":"guide/building-your-project.md","filePath":"guide/building-your-project.md","lastUpdated":1785719861000}'),o={name:"guide/building-your-project.md"};function r(d,e,n,h,l,c){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="building-your-project" tabindex="-1">Building Your Project <a class="header-anchor" href="#building-your-project" aria-label="Permalink to &quot;Building Your Project&quot;">​</a></h1><p>You can rebuild your generated project using the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mvnw</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mvnw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Pintegration-test</span></span></code></pre></div><p>The parameter <code>-Pintegration-test</code> triggers the integration tests.</p><h2 id="build-artifacts" tabindex="-1">Build Artifacts <a class="header-anchor" href="#build-artifacts" aria-label="Permalink to &quot;Build Artifacts&quot;">​</a></h2><p>Building the sample project produces the following artifacts - listed in alphabetic order:</p><dl><dt><code>keygen/src/main/resources/${privateKeyStoreFile}</code></dt><dd><p>The private key store - see below.</p><p> </p></dd><dt><code>keygen/target/${artifactId}-keygen-${version}-standalone.jar</code></dt><dd><p>This is the standalone JAR for the Key Generator module. It is generated by bundling the regular JAR with all its dependency JARs. This is convenient to use on the command line because you just have to add this JAR to the class path. <strong>You should never distribute this JAR!</strong></p></dd><dt><code>keygen/target/${artifactId}-keygen-${version}.jar</code></dt><dd><p>This is the regular JAR for the Key Generator module. This JAR has dependencies on other JARs as specified in the Maven <a href="https://maven.apache.org/guides/introduction/introduction-to-the-pom.html" target="_blank" rel="noreferrer">POM</a> for this module. <strong>You should never distribute this JAR!</strong></p></dd><dt><code>keymgr/src/main/resources/${ftpKeyStoreFile}</code></dt><dd><p>The FTP key store - see below.</p></dd><dt><code>keymgr/src/main/resources/${publicKeyStoreFile}</code></dt><dd><p>The public key store - see below.</p></dd><dt><code>keymgr/target/${artifactId}-keymgr-${version}-guarded.jar</code></dt><dd><p>This is the obfuscated standalone JAR for the Key Manager module. It is generated from the standalone JAR by obfuscating its byte code. This improves the security by making attacks on the byte code pretty hard - but not impossible. <strong>This is the only JAR which is intended for distribution.</strong></p></dd><dt><code>keymgr/target/${artifactId}-keymgr-${version}-standalone.jar</code></dt><dd><p>This is the standalone JAR for the Key Manager module. It is generated by bundling the regular JAR with all its dependency JARs. This is convenient to use on the command line because you just have to add this JAR to the class path. <strong>You should not distribute this JAR without additional obfuscation.</strong></p></dd><dt><code>keymgr/target/${artifactId}-keymgr-${version}.jar</code></dt><dd><p>This is the regular JAR for the Key Manager module. This JAR has dependencies on other JARs as specified in the Maven POM for this module. <strong>You should not distribute this JAR without additional obfuscation.</strong></p></dd><dt><code>keymgrsrv/target/${artifactId}-keymgrsrv-${version}.jar</code></dt><dd><p>This is the regular JAR for the Key Manager Service module. This JAR has dependencies on other JARs as specified in the Maven POM for this module. <strong>You should not distribute this JAR.</strong></p></dd></dl><h3 id="generated-keystore-files" tabindex="-1">Generated Keystore Files <a class="header-anchor" href="#generated-keystore-files" aria-label="Permalink to &quot;Generated Keystore Files&quot;">​</a></h3><p>When you run the build for the first time, the following keystore files get generated:</p><ul><li><code>keygen/src/main/resources/${privateKeyStoreFile}</code></li><li><code>keymgr/src/main/resources/${ftpKeyStoreFile}</code></li><li><code>keymgr/src/main/resources/${publicKeyStoreFile}</code></li></ul><p>You can use the following command to inspect the entries in the generated key store files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">keytool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -protected</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keystore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ${keyStorePath} </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-storetype</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ${keyStoreType}</span></span></code></pre></div><p>… where you need to replace <code>${keyStorePath}</code> with the respective path of the keystore file and <code>${keyStoreType}</code> with the keystore type which is configured in the parent POM file <code>pom.xml</code>, e.g. <code>JCEKS</code>, <code>JKS</code> or <code>PKCS12</code>.</p><p>The output of this command will show you a lot of metadata information: The distinguished name of the key pair owner and issuer, the validity period of the certificate etc. However, TrueLicense only reads the key, its digital signature algorithm and its signature - all other metadata gets ignored.</p>',14)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
